cellar.getInfo.snippet:
const info = await sdk.cellar.getInfo();
if (info.empty) {
    return "Empty cellar";
}
return info.counts.bottles + " bottles in " + info.counts.wines + " wines";

cellar.wine.getAll.snippet:
const wines = await sdk.cellar.wine.getAll();
console.log(wines.count + " wines");
return wines.map(w => w.name).toArray();

network.fetchBase64.snippet:
const b64 = await sdk.network.fetchBase64("https://example.com/image.png");
const big = await sdk.network.fetchBase64({ url: "https://example.com/big.pdf", timeout: 120000 });
return b64?.base64.length;

network.upload.snippet:
const file = await sdk.backup.createBackupFile();
const res = await sdk.network.upload({ path: file.path, url: "https://example.com/upload", method: "PUT" });
return res.status;

dialog.pick.snippet:
const wine = await sdk.dialog.pick({
  title: "Choose a wine",
  items: [{ id: "w1", text: "Margaux 2015" }, { id: "w2", text: "Pomerol 2016" }]
});
return wine?.id ?? null;

dialog.pickMany.snippet:
const wines = await sdk.dialog.pickMany({
  title: "Choose wines",
  selected: ["w1"],
  items: [{ id: "w1", text: "Margaux 2015" }, { id: "w2", text: "Pomerol 2016" }]
});
return wines?.map(w => w.id) ?? null;

backup.enable.snippet:
const ok = await sdk.backup.enable();
if (!ok) {
    await sdk.backup.open();
}
return ok;

ploud.syncNow.snippet:
const ok = await sdk.ploud.syncNow();
if (!ok) {
    const info = await sdk.ploud.getInfo();
    return info.cellarLocked ? "Cellar locked" : "Sync not possible";
}
return "Sync started";

pdf.createFile.snippet:
const wines = await sdk.cellar.wine.find("Margaux");
const file = await sdk.pdf.createFile(wines.toArray().map(w => w.id));
if (file) {
    await sdk.ui.shareFiles(file.path);
}

translations.get.snippet:
const title = await sdk.translations.get("wine.title");
const texts = await sdk.translations.get(["wine.title", "wine.vintage"]);
await sdk.dialog.alert(texts["wine.vintage"]);

files.writeBase64.snippet:
const file = await sdk.files.writeBase64("hello.txt", btoa("Hello"));
const same = await sdk.files.writeBase64({ path: "hello.txt", base64: btoa("Hello") });
return file;

